  const [syncFieldsLoading, setSyncFieldsLoading] = useState(false);
  const handleSyncFields = async () => {
    if (!registry) return;
    setSyncFieldsLoading(true);
    const trace = createActionTrace('sync_fields_to_shadow');
    try {
      const scopedBindingID = bindingIdParam ? Number(bindingIdParam) : registry.shadow_binding_id;
      const bindingQuery = scopedBindingID != null && scopedBindingID > 0
        ? `?binding_id=${scopedBindingID}`
        : '';
      const endpoint = `/api/v1/source-objects/${registry.id}/create-default-columns${bindingQuery}`;
      const { data } = await cmsApi.post(endpoint, actionTraceBody(trace), {
        headers: actionTraceHeaders(trace),
      });
      message.success(`Đang cập nhật field vào shadow table... trace=${data?.trace_id || trace.traceId}`);
    } catch (err) {
      message.error(humanizeApiError(err, 'Cập nhật field thất bại'));
    } finally {
      setSyncFieldsLoading(false);
    }
  };

