func (sa *SchemaAdapter) AlterColumn(ctx context.Context, schemaName, tableName, columnName, dataType, action string) error {
	qualifiedTable := fmt.Sprintf(`"%s"`, tableName)
	if schemaName != "" {
		qualifiedTable = fmt.Sprintf(`"%s"."%s"`, schemaName, tableName)
	}
	var sql string
	switch strings.ToLower(action) {
	case "add":
		sql = fmt.Sprintf(`ALTER TABLE %s ADD COLUMN IF NOT EXISTS "%s" %s`, qualifiedTable, columnName, dataType)
	case "drop":
		sql = fmt.Sprintf(`ALTER TABLE %s DROP COLUMN IF EXISTS "%s"`, qualifiedTable, columnName)
	case "alter_type":
		sql = fmt.Sprintf(`ALTER TABLE %s ALTER COLUMN "%s" TYPE %s USING "%s"::%s`,
			qualifiedTable, columnName, dataType, columnName, dataType)
	default:
		return fmt.Errorf("invalid alter action: %s", action)
	}
	return sa.db.WithContext(ctx).Exec(sql).Error
}

